class Solution:
    def findLatestTime(self, s: str) -> str:
        r = list(s)
        if r[0] == '?':
            r[0] = '1' if r[1] == '?' or r[1] <= '1' else '0'
        if r[1] == '?':
            r[1] = '1' if r[0] == '1' else '9'
        if r[3] == '?':
            r[3] = '5'
        if r[4] == '?':
            r[4] = '9'
        return ''.join(r)

