class Solution {
    public String findLatestTime(String s) {
        char[] r = s.toCharArray();
        if (r[0] == '?') r[0] = (r[1] == '?' || r[1] <= '1') ? '1' : '0';
        if (r[1] == '?') r[1] = (r[0] == '1') ? '1' : '9';
        if (r[3] == '?') r[3] = '5';
        if (r[4] == '?') r[4] = '9';
        return new String(r);
    }
}

