class Solution:
    def findLatestTime(self, s: str) -> str:
        for t in range(719, -1, -1):
            c = f"{t // 60:02d}:{t % 60:02d}"
            if all(s[i] == '?' or s[i] == c[i] for i in range(5)):
                return c
        return ""

