class Solution {
public:
    string findLatestTime(string s) {
        for (int t = 719; t >= 0; t--) {
            char buf[6];
            snprintf(buf, 6, "%02d:%02d", t / 60, t % 60);
            bool ok = true;
            for (int i = 0; i < 5; i++)
                if (s[i] != '?' && s[i] != buf[i]) { ok = false; break; }
            if (ok) return string(buf);
        }
        return "";
    }
};

