var findLatestTime = function(s) {
    for (let t = 719; t >= 0; t--) {
        const c = String(Math.floor(t / 60)).padStart(2, '0') + ':' +
                  String(t % 60).padStart(2, '0');
        let ok = true;
        for (let i = 0; i < 5; i++)
            if (s[i] !== '?' && s[i] !== c[i]) { ok = false; break; }
        if (ok) return c;
    }
    return "";
};
